function drawBrazier(x,y){let glow=ctx.createRadialGradient(x,y,2,x,y,58);glow.addColorStop(0,'#f2a94b38');glow.addColorStop(1,'#f2a94b00');ctx.fillStyle=glow;ctx.fillRect(x-58,y-58,116,116);ctx.fillStyle='#292d29';ctx.fillRect(x-10,y-8,20,20);ctx.fillStyle='#836b46';ctx.fillRect(x-12,y-11,24,7);ctx.fillStyle='#eea64c';ctx.beginPath();ctx.moveTo(x,y-35);ctx.quadraticCurveTo(x+17,y-15,x,y-9);ctx.quadraticCurveTo(x-15,y-16,x,y-35);ctx.fill();ctx.fillStyle='#ffe2a0';ctx.beginPath();ctx.ellipse(x,y-17,4,10,0,0,Math.PI*2);ctx.fill()}
function drawStandards(){for(const [i,s] of standards){ } for(let i=0;i<standards.length;i++){let s=standards[i],col=s.done?s.color:'#666257';ctx.fillStyle='#222826';ctx.beginPath();ctx.ellipse(s.x,s.y+25,31,12,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#786a4e';ctx.fillRect(s.x-4,s.y-47,8,72);ctx.fillStyle=s.done?s.color:'#79776b';ctx.beginPath();ctx.moveTo(s.x+3,s.y-45);ctx.lineTo(s.x+39,s.y-34);ctx.lineTo(s.x+3,s.y-19);ctx.closePath();ctx.fill();ctx.fillStyle=s.done?'#e1d3ac':'#aaa58e';ctx.font='bold 14px Cinzel';ctx.textAlign='center';ctx.fillText(i===0?'✦':i===1?'✕':'✧',s.x+15,s.y-31);if(!s.done){ctx.strokeStyle='#d9c89b55';ctx.setLineDash([3,5]);ctx.beginPath();ctx.arc(s.x,s.y,39,0,Math.PI*2);ctx.stroke();ctx.setLineDash([])}}}
function drawTrees(){for(const t of trees){ctx.fillStyle='#202827';ctx.beginPath();ctx.ellipse(t.x+4,t.y+8,t.r*.9,t.r*.56,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#514d40';ctx.fillRect(t.x-5,t.y-7,10,20);let c=t.variant>.55?'#35463f':'#34403b';ctx.fillStyle=c;ctx.beginPath();ctx.arc(t.x,t.y-7,t.r,0,Math.PI*2);ctx.fill();ctx.fillStyle='#435348';ctx.beginPath();ctx.arc(t.x-t.r*.25,t.y-t.r*.28,t.r*.58,0,Math.PI*2);ctx.fill();ctx.fillStyle='#aab4aa';ctx.globalAlpha=.6;ctx.beginPath();ctx.arc(t.x+t.r*.23,t.y-t.r*.56,t.r*.28,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}}
